  {"note": "Pre-check (read-only): fail early, before touching anything, if an INVALID index named orders_customer_id_idx exists (e.g. a half-finished earlier CONCURRENTLY build), because IF NOT EXISTS below would silently skip it. On the live database today the index already exists and is valid, so this passes.",
   "sql": "DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid WHERE c.relname = 'orders_customer_id_idx' AND i.indrelid = 'public.orders'::regclass AND NOT (i.indisvalid AND i.indisready AND i.indislive)) THEN RAISE EXCEPTION 'orders_customer_id_idx exists but is invalid: drop it with DROP INDEX CONCURRENTLY and rerun'; END IF; END $$;"},
  {"note": "Build the index without blocking traffic. CONCURRENTLY takes only a SHARE UPDATE EXCLUSIVE lock, so the app's INSERTs and SELECTs keep running throughout. (customer_id, id) serves the customer page's WHERE customer_id = $1 ORDER BY id DESC LIMIT 10 directly from the index. IF NOT EXISTS makes this a no-op when the index is already there (it is, on the live database today). It's a step by itself because CREATE INDEX CONCURRENTLY cannot run inside a transaction block.",
   "sql": "CREATE INDEX CONCURRENTLY IF NOT EXISTS orders_customer_id_idx ON public.orders (customer_id, id);"},
  {"note": "Post-check (read-only): make sure a valid, ready index whose first column is customer_id now exists on orders. Otherwise the plan fails loudly.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = 'public.orders'::regclass AND i.indisvalid AND i.indisready AND i.indislive AND i.indkey[0] = (SELECT attnum FROM pg_attribute WHERE attrelid = 'public.orders'::regclass AND attname = 'customer_id')) THEN RAISE EXCEPTION 'no valid index on orders(customer_id)'; END IF; END $$;"}
